// Next.js API route support: https://nextjs.org/docs/api-routes/introduction
import type { NextApiRequest, NextApiResponse } from 'next'

type Data = {
  name: string
}

export default function handler(
  req: NextApiRequest,
  res: NextApiResponse<Data>
) {
  res.status(200).json({ name: 'John Doe' })
}

import { useMachine } from "@xstate/react";
import { createMachine } from "xstate";
import { createFormModel } from "../lib/createFormService";
import { ContextFromFormModel, EventsFromFormModel } from "../lib/types";

const formModel = createFormModel("loginForm", {
  initialValues: {
    username: "",
    password: "",
  },
  validate: (values) => {
    if (!values.username) {
      return {
        username: "You must pass a username!",
      };
    }
  },
});

const machine = createMachine<
  ContextFromFormModel<typeof formModel>,
  EventsFromFormModel<typeof formModel>
>({
  initial: "gettingDetails",
  context: {
    loginForm: formModel.initialContext,
  },
  states: {
    gettingDetails: formModel.createState({
      on: {
        "loginForm.SUBMIT": {
          cond: formModel.selectors.getIsValid,
          actions: [
            formModel.actions.assignSubmitToState,
            (context: ContextFromFormModel<typeof formModel>) => {
              alert(JSON.stringify(context.loginForm));
            },
          ],
        },
      },
    }),
  },
});

const NextPage = () => {
  const [state, send] = useMachine(machine);

  const formInfo = formModel.makeHandlers(state.context, send);

  return (
    <form onSubmit={formInfo.onSubmit}>
      <input {...formInfo.register("username")} placeholder="username"></input>
      <input {...formInfo.register("password")} placeholder="password"></input>
      <pre>{JSON.stringify(formInfo.errors)}</pre>
      <button type="submit">Submit</button>
      <button type="reset" onClick={formInfo.reset}>
        Reset
      </button>
    </form>
  );
};

export default NextPage;

import { ChangeEvent } from "react";
import { AssignAction, EventObject, StateNodeConfig, assign } from "xstate";
import { Model } from "xstate/lib/model.types";
import {
  BooleanMap,
  FormContext,
  FormModel,
  FormModelActions,
  FormModelEvents,
  FormModelParams,
  FormModelSelectors,
  InitialState,
  RegisterOutput,
} from "./types";

const toInitialBooleanMap = <Values extends {}>(
  values: Values,
): BooleanMap<Values> => {
  const map = {} as BooleanMap<Values>;
  Object.keys(values).forEach((key) => {
    (map as any)[key] = false;
  });
  return map;
};

export const makeInitialStateFromConfig = <Values extends {}>(
  config: FormModelParams<Values>,
): InitialState<Values> => {
  return {
    values: config.initialValues,
    errors: config.validate?.(config.initialValues) || {},
    touched: toInitialBooleanMap(config.initialValues),
    submitCount: 0,
  };
};

export const createFormModel = <Key extends string, Values extends {}>(
  key: Key,
  config: FormModelParams<Values>,
): FormModel<Key, Values> => {
  const events: FormModelEvents<Key, Values> = {
    change: (name, value) => {
      return {
        type: `${key}.CHANGE`,
        name,
        value,
      };
    },
    blur: (name, value) => {
      return {
        type: `${key}.BLUR`,
        name,
        value,
      };
    },
    focus: (name) => {
      return {
        type: `${key}.FOCUS`,
        name,
      };
    },
    submit: (values) => {
      return {
        type: `${key}.SUBMIT`,
        values,
      };
    },
    reset: () => {
      return {
        type: `${key}.RESET`,
      };
    },
  };

  const actions: FormModelActions<Key, Values> = {
    assignChangeToState: assign((context, event) => {
      const newValues: Values = {
        ...context[key].values,
        [event.name]: event.value,
      };
      return {
        [key]: {
          ...context[key],
          values: newValues,
          errors: config.validate?.(newValues) || {},
        },
      } as FormContext<Key, Values>;
    }),
    assignBlurToState: assign((context, event) => {
      const newValues: Values = {
        ...context[key].values,
        [event.name]: event.value,
      };

      return {
        [key]: {
          ...context[key],
          values: newValues,
          errors: config.validate?.(newValues) || {},
        },
      } as FormContext<Key, Values>;
    }),
    assignFocusToState: assign((context, event) => {
      return {
        [key]: {
          ...context[key],
          touched: {
            ...context[key].touched,
            [event.name]: true,
          },
        },
      } as unknown as FormContext<Key, Values>;
    }),
    assignSubmitToState: assign((context, event) => {
      return {
        [key]: {
          ...context[key],
          submitCount: context[key].submitCount + 1,
        },
      } as unknown as FormContext<Key, Values>;
    }),
    reset: assign((context, event) => {
      return {
        [key]: makeInitialStateFromConfig(config),
      } as unknown as FormContext<Key, Values>;
    }),
  };

  const createState = <
    TContext extends FormContext<Key, Values>,
    TEvent extends EventObject,
  >(
    config: StateNodeConfig<TContext, any, TEvent>,
  ): StateNodeConfig<TContext, any, TEvent> => {
    return {
      ...config,
      on: {
        [`${key}.CHANGE`]: {
          actions: [actions.assignChangeToState],
        },
        [`${key}.BLUR`]: {
          actions: [actions.assignBlurToState],
        },
        [`${key}.FOCUS`]: {
          actions: [actions.assignFocusToState],
        },
        [`${key}.RESET`]: {
          actions: [actions.reset],
        },
        ...config.on,
      },
    };
  };

  const initialContext = makeInitialStateFromConfig(config);

  const getIsDirty: FormModelSelectors<Key, Values>["getIsDirty"] = (
    context,
  ) => {
    return Object.values(context[key].touched).some(Boolean);
  };

  const selectors: FormModelSelectors<Key, Values> = {
    getIsValid: (context) => {
      return Object.keys(context[key].errors).length === 0;
    },
    getIsDirty,
    getIsPristine: (context) => !getIsDirty(context),
  };

  return {
    key,
    initialContext,
    events,
    createState,
    selectors,
    actions,
    makeHandlers: (context, send) => {
      const register = (name: keyof Values): RegisterOutput => {
        return {
          name: name as string,
          onChange: (e: { target: { value: string } }) => {
            send(events.change(name, e.target.value));
          },
          onBlur: (e) => {
            send(events.blur(name, e.target.value));
          },
          onFocus: (e) => {
            send(events.focus(name));
          },
          value: context[key].values[name] as any,
          error: context[key].errors[name] || undefined,
          touched: context[key].touched[name],
        };
      };

      return {
        register,
        onSubmit: (e) => {
          e?.preventDefault?.();
          console.log(e);
          send(events.submit({} as any));
        },
        errors: context[key].errors,
        submitCount: context[key].submitCount,
        touched: context[key].touched,
        values: context[key].values,
        reset: () => {
          send(events.reset());
        },
      };
    },
  };
};

import { ChangeEvent } from "react";
import { AssignAction, EventObject, State, StateNodeConfig } from "xstate";
import { Model } from "xstate/lib/model.types";

export interface FormModel<Key extends string, Values> {
  key: Key;
  initialContext: InitialState<Values>;
  events: FormModelEvents<Key, Values>;
  createState: <
    TContext extends FormContext<Key, Values>,
    TEvent extends EventObject,
  >(
    config: StateNodeConfig<TContext, any, TEvent>,
  ) => StateNodeConfig<TContext, any, TEvent>;
  selectors: FormModelSelectors<Key, Values>;
  actions: FormModelActions<Key, Values>;
  makeHandlers: <TContext extends FormContext<Key, Values>>(
    state: TContext,
    send: (event: any) => void,
  ) => {
    register: Register<Values>;
    onSubmit: (e: any) => void;
    values: Values;
    errors: ErrorsFromValues<Values>;
    touched: BooleanMap<Values>;
    submitCount: number;
    reset: () => void;
  };
}

export type Register<Values> = (name: keyof Values) => RegisterOutput;

export interface RegisterOutput {
  name: string;
  value: string;
  onChange: (e: any) => void;
  onBlur: (e: any) => void;
  onFocus: (e: any) => void;
  error: string | undefined;
  touched: boolean;
}

export type FormContext<Key extends string, Values> = {
  [K in Key]: InitialState<Values>;
};

export interface FormModelSelectors<Key extends string, Values> {
  getIsValid: <TContext extends FormContext<Key, Values>>(
    context: TContext,
  ) => boolean;
  getIsDirty: <TContext extends FormContext<Key, Values>>(
    context: TContext,
  ) => boolean;
  getIsPristine: <TContext extends FormContext<Key, Values>>(
    context: TContext,
  ) => boolean;
}

export interface FormModelEvents<Key extends string, Values> {
  change: <ValueName extends keyof Values>(
    name: ValueName,
    value: string,
  ) => {
    type: `${Key}.CHANGE`;
    name: ValueName;
    value: string;
  };
  blur: <ValueName extends keyof Values>(
    name: ValueName,
    value: string,
  ) => {
    type: `${Key}.BLUR`;
    name: ValueName;
    value: string;
  };
  focus: <ValueName extends keyof Values>(
    name: ValueName,
  ) => {
    type: `${Key}.FOCUS`;
    name: ValueName;
  };
  submit: (values: Values) => {
    type: `${Key}.SUBMIT`;
    values: Values;
  };
  reset: () => {
    type: `${Key}.RESET`;
  };
}

export interface FormModelActions<Key extends string, Values> {
  assignChangeToState: AssignAction<FormContext<Key, Values>, any>;
  assignBlurToState: AssignAction<FormContext<Key, Values>, any>;
  assignFocusToState: AssignAction<FormContext<Key, Values>, any>;
  assignSubmitToState: AssignAction<FormContext<Key, Values>, any>;
  reset: AssignAction<FormContext<Key, Values>, any>;
}

export type FormEvents<Key extends string, Values> = {
  [K in keyof FormModelEvents<Key, Values>]: ReturnType<
    FormModelEvents<Key, Values>[K]
  >;
}[keyof FormModelEvents<Key, Values>];

export type EventsFromFormModel<T> = T extends FormModel<
  infer Key,
  infer Values
>
  ? FormEvents<Key, Values>
  : never;

export type ContextFromFormModel<T> = T extends FormModel<
  infer Key,
  infer Values
>
  ? FormContext<Key, Values>
  : never;

export type ModelFromFormModel<T> = T extends FormModel<infer Key, infer Values>
  ? Model<FormContext<Key, Values>, FormEvents<Key, Values>>
  : never;

export interface FormModelParams<Values> {
  initialValues: Values;
  validate?: ValidateFunction<Values>;
}

export type ValidateFunction<Values> = (
  value: Values,
) => ErrorsFromValues<Values> | void;

export type ErrorsFromValues<Values> = {
  [K in keyof Values]?: string;
};

export type BooleanMap<Values> = {
  [K in keyof Values]: boolean;
};

export interface InitialState<Values> {
  errors: ErrorsFromValues<Values>;
  touched: BooleanMap<Values>;
  values: Values;
  submitCount: number;
}

